printf '%s\n' 'import json' 'import sys' '' 'path = sys.argv[1]' 'try:' '    with open(path) as f:' '        cfg = json.load(f)' 'except (OSError, ValueError) as err:' '    sys.exit("error: cannot read %s: %s" % (path, err))' 'missing = [key for key in ("app", "defaults") if key not in cfg]' 'if missing:' '    sys.exit("error: missing key: " + ", ".join(missing))' 'print("ok")' > validate_config.py
